export const modules=[['overview','Overview'],['support','Support inbox'],['support-website','Website chats'],['support-whatsapp','WhatsApp chats'],['support-messenger','Messenger chats'],['orders','Orders'],['manual','Manual sales'],['products','Products'],['inventory','Inventory'],['purchases','Purchases'],['suppliers','Suppliers'],['customers','Customers'],['accounts','Accounts'],['payments','Payments'],['courier','Courier'],['returns','Returns'],['reports','Reports'],['coupons','Marketing'],['content','Content'],['seo','SEO'],['team','Team & access'],['audit','Audit log'],['settings','Settings']];
export const actions=['view','create','edit','delete'];
export const fullPermissions=()=>Object.fromEntries(modules.map(([id])=>[id,[...actions]]));
export function permissionSet(s){const person=s.previewStaff?s.records.staff.find(p=>p.id===s.previewStaff):null;if(person?.status==='Disabled')return {};const role=person?.role||s.previewRole||'Super Admin';if(role==='Super Admin')return fullPermissions();return person?.customPermissions||s.roles?.[role]||{};}
export function can(s,module,action='view'){if(module==='owner-ai')return !s.previewStaff&&(s.previewRole||'Super Admin')==='Super Admin';if(module==='welcome-popup')module='content';if(module==='reviews')module='products';if(module==='archive')return Object.values(permissionSet(s)).some(p=>p.includes('view'));if(module==='banners')module='coupons';return permissionSet(s)[module]?.includes(action)||false;}
export function requirePermission(s,module,action='view'){if(!can(s,module,action))throw Error('This staff role does not have '+action+' access to '+module+'.');}
